// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2014, "2-3", [{"author":"Б. Иомдин","question":"Когда ребятам что-то очень нравится, они говорят...","choices":["<em>Имя!</em>","<em>Отчество!</em>","<em>Фамилия!</em>","<em>Школа!</em>","<em>Класс!</em>"],"key":"Д","review":["Когда всё нравится","Прочитай варианты как возгласы. Ищи слово, которым хвалят что-то удачное, например рисунок или подарок.","«Класс!» значит «Здорово!» В таком возгласе имеется в виду, что что-то очень понравилось."]},{"author":"Л. Добрушин и Е. Добрушина","question":"При написании какого из этих слов дважды используется одно и то же правило?","choices":["<em>щука</em>","<em>чудо</em>","<em>чаща</em>","<em>шило</em>","<em>лыжи</em>."],"key":"В","review":["Одно правило дважды","Найди сочетания «чу», «щу», «ча», «ща», «жи» или «ши». Письмо таких сочетаний подчиняется знакомым правилам.","В «чаща» есть сразу «ча» и «ща». В обоих случаях после шипящей пишется а по правилу «ча-ща пиши с а»."]},{"author":"Л. Фёдорова","question":"У чего не бывает крышки?","choices":["у кастрюли","у сковороды","у шкатулки","у сундука","у избушки."],"key":"Д","review":["Предметы с крышками","Кастрюлю, сковороду, шкатулку и сундук можно накрыть крышкой. Она закрывает то, что внутри.","Сверху у избушки крыша. Она часть дома и называется иначе, чем крышка у ёмкости."]},{"author":"И. Иткин","question":"<em>Сестра</em> — <em>сёстры</em>, <em>стол</em> — <em>столы</em>, <em>голос</em> — <em>голоса</em>, <em>плечо</em> — <em>плечи</em>, <em>брат</em> — ... .","choices":["<em>браты</em>","<em>брата</em>","<em>братья</em>","<em>братия</em>","<em>братики</em>."],"key":"В","review":["Один и много","В примерах первое слово обозначает один предмет, второе — несколько. Подставь слово «брат» в выражение «все мои …».","Правильно «мои братья». «Брата» годится, например, после «два», а «братики» звучит ласково."]},{"author":"К. Гилярова","question":"<em>Здравствуйт_</em>, <em>до свидани_</em>, <em>спасиб_</em>, <em>пожалуйст_</em>, <em>извинит_</em>.\nКакой буквой нельзя заполнить ни один из пропусков?","choices":["<em>а</em>","<em>о</em>","<em>и</em>","<em>е</em>","<em>я</em>."],"key":"В","review":["Последние буквы","Восстанови слова по знакомым вежливым выражениям. В «здравствуйте» и «извините» конец е, в «до свидания» — я.","«Спасибо» заканчивается на о, «пожалуйста» — на а. Буква и в этих пропусках не понадобилась."]},{"author":"Б. Иомдин","question":"В подписи под фотографией стёрлось число: «... годика». А какое оно было, скорее всего?","choices":["1","3","5","22","33."],"key":"Б","review":["Подпись к фотографии","«Годика» обычно говорят о возрасте маленького ребёнка. Попробуй прочитать «один годик», «три годика», «пять годиков».","Из трёх маленьких чисел только 3 даёт форму «годика». Числа 22 и 33 по форме подходят, но про взрослых редко говорят «годика»."]},{"author":"С. Переверзева","question":"Корова говорит «Му!», собака ― «Гав!», кошка ― «Мяу!». А кто говорит самое длинное «слово»?","choices":["утка","свинья","лошадь","лягушка","петух."],"key":"Д","review":["Голоса животных","Произнеси, как подают голос утка, свинья, лошадь и лягушка. Это «кря», «хрю», «и-го-го» и «ква».","Петух говорит «ку-ка-ре-ку». В его «слове» четыре слога, больше, чем у остальных."]},{"author":"И. Иткин","question":"В древнегреческом языке буква <em>альфа</em> обозначала звук [а], буква <em>мю</em> ― звук [м]. Какой звук обозначала буква <em>тау</em>?","choices":["[б]","[в]","[н]","[т]","[у]."],"key":"Г","review":["Греческая буква","В названиях «альфа» и «мю» звуки [а] и [м] стоят в начале. Примени тот же способ к «тау».","Название «тау» начинается со звука [т]. Поэтому в этих примерах букве тау соответствует [т]."]},{"author":"А. Сомин","question":"Какую вывеску можно увидеть на почте?","choices":["посылка отправок","поправка отсылок","отправка посылок","отсылка поправок","заправка присылок."],"key":"В","review":["Почтовая вывеска","Вспомни, что приносят на почту, чтобы это отправили получателю. Это письма или посылки.","На вывеске нужно название услуги. Она называется «отправка посылок»."]},{"author":"Л. Фёдорова","question":"Какое из этих сказочных имён ни к чему не призывает?","choices":["<em>Дуремар</em>","<em>Вырвидуб</em>","<em>Тяни-Толкай</em>","<em>Покатигорошек</em>","<em>Мойдодыр</em>."],"key":"А","review":["Имена и команды","Раздели имена на части. Слышно «вырви дуб», «тяни, толкай», «покати горошек», «мой до дыр». Это команды.","В имени Дуремар слова-команды нет. Поэтому это имя ни к чему не призывает."]},{"author":"Б. Иомдин","question":"Какой вопрос можно закончить и словами <em>наш сосед</em>, и словами <em>наши</em> <em>соседи</em>?","choices":["<em>Ты</em> …<em>?</em>","<em>Вы</em> …<em>?</em>","<em>Он</em> …<em>?</em>","<em>Она</em> …<em>?</em>","никакой."],"key":"Б","review":["Как обратиться к соседям","Если перед тобой несколько людей, спроси «Вы наши соседи?» Местоимение «вы» относится сразу ко всем.","«Вы» можно вежливо сказать и одному человеку: «Вы наш сосед?» Остальные местоимения в списке не подходят для обращения к нескольким людям."]},{"author":"Л. Фёдорова","question":"Настя побывала в зоопарке и пишет сочинение: <em>У каждого зверя в зоопарке есть своя пара: у слона ― слониха, у лося ― лосиха,</em> <em>у зайца ― зайчиха, ...</em> . Какая пара не подойдёт, чтобы продолжить предложение?","choices":["<em>у лисы ― лисица</em>","<em>у медведя ― медведица</em>","<em>у волка ― волчица</em>","<em>у льва ― львица</em>","<em>у тигра ― тигрица</em>."],"key":"А","review":["Пары в зоопарке","У слона и слонихи, лося и лосихи взрослого самца и самку называют разными словами. Попробуй так же понять остальные пары.","«Лиса» и «лисица» называют одну и ту же самку. Чтобы составить пару по образцу, нужно сказать «у лиса — лисица»."]},{"author":"А. Сомин","question":"<em>Футбол</em>, <em>волейбол</em>, <em>теннис</em>, <em>бокс</em>. Выберите в правильном порядке названия мест, где занимаются этими видами спорта:","choices":["<em>корт</em>, <em>площадка</em>, <em>поле</em>, <em>ринг</em>","<em>поле</em>, <em>площадка</em>, <em>корт</em>, <em>ринг</em>","<em>ринг</em>, <em>поле</em>, <em>площадка</em>, <em>корт</em>","<em>площадка</em>, <em>корт</em>, <em>поле</em>, <em>ринг</em>","<em>поле</em>, <em>ринг</em>, <em>корт</em>, <em>площадка</em>."],"key":"Б","review":["Где занимаются спортом","Футболисты играют на поле, а волейболисты — на площадке. В ответе эти слова должны идти первыми.","Теннисисты играют на корте, а боксёры сражаются на ринге. Весь порядок — поле, площадка, корт, ринг."]},{"author":"Е. Муравенко","question":"<em>Дождь</em>, <em>снег</em>, <em>иней</em>. Что может и идти, и лежать?","choices":["только <em>дождь</em>","только <em>снег</em>","только <em>иней</em>","и <em>дождь</em>, и <em>иней</em>","и <em>снег</em>, и <em>иней</em>."],"key":"Б","review":["Погода в двух словах","Скажи «идёт дождь» и «идёт снег». Иней образуется на холодной поверхности и про него обычно говорят «покрыл» или «лежит».","Снег может падать с неба и лежать на земле. Дождь идёт, а его вода после этого собирается в лужи."]},{"author":"Б. Иомдин","question":"<em>Зачем это хта — обязательно та,</em>\n<em>А жерка, как правило, эта?</em>\nПро какие предметы мебели пел Винни-Пух?","choices":["про хту и жерку","про этухту и тужерку","про тухту и этужерку","про тахту и этажерку","про этахту и тажерку."],"key":"Г","review":["Песенка Винни-Пуха","Соедини «та» и «хта», которые в песенке оказались раздельно. Получится «тахта», широкая кушетка.","Соедини «эта» и «жерка». Получится «этажерка», полки для вещей. Это и есть два предмета мебели."]},{"author":"Б. Иомдин","question":"От многих слов, обозначающих предметы, можно образовать уменьшительные слова: <em>дом</em> — <em>домик</em>, <em>книга</em> — <em>книжка</em>, <em>поле</em> — <em>полюшко</em>. В каком ответе второе слово — уменьшительное от первого?","choices":["<em>беседа — беседка</em>","<em>быль</em> — <em>былинка</em>","<em>речь — речка</em>","<em>рассказ — рассказик</em>","<em>часть — частушка.</em>"],"key":"Г","review":["Маленький предмет","Проверь, сохраняет ли второе слово предмет первого. Беседка — строение, речка — небольшой водоём, а частушка — песенка. Это новые значения.","«Рассказик» — небольшой рассказ. «Былинка» значит травинка, поэтому к слову «быль» она по смыслу не подходит."]},{"author":"Л. Фёдорова","question":"В Королевстве кривых зеркал, куда попала Оля, у неё оказалась подружка Яло — её зеркальное отражение. Оля записала под диктовку Яло имена жителей этого королевства, но в одном ошиблась. В каком из имён ошибка?","choices":["<em>Абаж</em>","<em>Анидаг</em>","<em>Аксал</em>","<em>Гурт</em>","<em>Нушрок</em>."],"key":"Г","review":["Имена в кривом зеркале","Запиши буквы каждого имени с конца, как в паре «Оля — Яло». Из Абаж, Анидаг, Аксал и Нушрок получатся «жаба», «гадина», «ласка» и «коршун».","Из «Гурт» получается «труг». Чтобы по тому же правилу записать «друг», нужно было написать «Гурд»."]},{"author":"Б. Иомдин","question":"Над магазином висит вывеска: <em>Вы____ка прямо из ____ки!</em> Что мы дважды пропустили в этой вывеске?","choices":["<em>пуш</em>","<em>руч</em>","<em>руб</em>","<em>тач</em>","<em>печ</em>."],"key":"Д","review":["Вывеска у магазина","Если магазин торгует хлебом и булочками, на вывеске можно сказать, что продаётся «выпечка». После «вы» для этого нужны буквы «печ».","Подставь «печ» и во второй пропуск. Получается «Выпечка прямо из печки!», и обе части вывески подходят друг к другу."]},{"author":"Б. Иомдин","question":"<em>Шла Саша по шоссе и сосала сушку</em> — это…","choices":["загадка","пословица","поговорка","скороговорка","считалка."],"key":"Г","review":["Фраза про Сашу","Прочитай фразу быстро несколько раз. В ней рядом повторяются похожие звуки [с] и [ш].","Фразы, на которых трудно сохранить чёткое произношение, называются скороговорками. Здесь задача — не перепутать «Саша», «шоссе» и «сушку»."]},{"author":"А. Сомин","question":"<em>Раньше от этого озорника житья не было, а теперь он стал как ...</em>","choices":["<em>шёлковый</em>","<em>бархатный</em>","<em>трикотажный</em>","<em>льняной</em>","<em>кружевной</em>."],"key":"А","review":["Озорник изменился","Из фразы понятно, что озорник стал послушным и спокойным. Ищи привычное сравнение для такого поведения.","Говорят «стал как шёлковый». Сравнение напоминает о мягкой и гладкой шёлковой ткани."]},{"author":"Б. Иомдин","question":"<em>Мне нужны такие вещи:</em>\n<em>Молоток, тиски и клещи,</em>\n<em>Ключ, напильник и ножовка,</em>\n<em>А всего нужней ― сноровка.</em>\nКак называется это стихотворение Б. Заходера?","choices":["«Дворник»","«Слесарь»","«Сапожник»","«Портной»","«Фокусник»."],"key":"Б","review":["Инструменты в стихах","Тиски зажимают деталь, напильник сглаживает её края, а ножовка может распилить металл.","Такой набор нужен мастеру, который обрабатывает и чинит детали. Стихотворение называется «Слесарь»."]},{"author":"Б. Иомдин","question":"Какое слово в древнерусском языке означало ‘младший сын’?","choices":["<em>близнец</em>","<em>братец</em>","<em>красавец</em>","<em>мизинец</em>","<em>первенец</em>."],"key":"Г","review":["Младший сын","«Первенец» — ребёнок, который родился первым. Для младшего сына ищи слово, связанное с самым маленьким.","Мизинец — самый маленький палец. В старину тем же словом могли звать младшего сына."]},{"author":"А. Сомин","question":"По названию <em>спаниель</em> можно догадаться, что эта порода собак происходит из ...","choices":["Сингапура","Польши","Японии","Исландии","Испании."],"key":"Д","review":["Откуда спаниель","Сравни начало «спаниель» и названия стран. В слове слышны буквы «спани».","Эта же последовательность есть в названии «Испания». Именно с этой страной связано название породы."]},{"author":"Л. Добрушин и Е. Добрушина","question":"Лёва составил список того, что выращивает в огороде его бабушка: <em>баклажаны, кабачки, картофель, морковь</em>, <em>огурцы</em>, <em>петрушка,</em> <em>помидоры</em>, <em>щавель</em>. Потом он вписал в список ещё одно слово после слова <em>картофель</em>. Какое?","choices":["<em>укроп</em>","<em>лук</em>","<em>капуста</em>","<em>репа</em>","<em>тыква</em>."],"key":"Б","review":["Бабушкин огород","Посмотри на первые буквы списка: Б, К, К, М, О, П, П, Щ. А внутри К и П сравни следующие буквы. Список идёт по алфавиту.","После «картофель» перед «морковь» подходит слово на Л. «Лук» — единственный такой вариант, а «капуста» встала бы до «картофель»."]},{"author":"К. Гилярова","question":"Какая часть дома по-голландски называется trap (читается «трап»)?","choices":["стена","крыша","дверь","окно","лестница."],"key":"Д","review":["Часть дома по-голландски","В русском есть слово «трап». Так называют лестницу, по которой поднимаются на корабль или в самолёт.","Голландское trap обозначает такую же часть дома — лестницу. Она соединяет этажи, как трап соединяет разные уровни."]},{"author":"С. Бурлак","question":"Во всех парах слова различаются ровно одним звуком, кроме одной.\nКакой?","choices":["<em>лама</em> ― <em>рама</em>","<em>шесть</em> ― <em>сесть</em>","<em>руки</em> ― <em>реки</em>","<em>палка</em> ― <em>полка</em>","<em>пил ― пел</em>."],"key":"В","review":["Пары по звукам","Сравни «руки» и «реки». В первом слове начало [р], [у], во втором — [р’], [э]. Меняются и согласный, и гласный.","В остальных парах меняется только один звук: [л] и [р], [ш] и [с’], [а] и [о], [и] и [э] соответственно."]},{"author":"Е. Кац","question":"Даня придумал простой способ зашифровки чисел. Число 57 он записывает как ПС, 179 — как ССД, 308 — как ТВ. Сколько разных чисел может означать запись ДО?","choices":["четыре","пять","шесть","семь","восемь."],"key":"В","review":["Данин шифр","Прочитай числа словами и возьми начала слов. «Пятьдесят семь» даёт ПС, «сто семьдесят девять» — ССД, «триста восемь» — ТВ.","ДО дают «двадцать один» и «девяносто один», а также «двести» и «девятьсот» с «один» или «одиннадцать». Это шесть чисел: 21, 91, 201, 211, 901, 911."]},{"author":"А. Пиперски","question":"Первоклассник Вася увидел перед собой список:\n<em>абрикос, ананас, банан, булка, грейпфрут, кабачок, котлета,</em> <em>огурец, репа, слойка, сок, суп</em>. Посмотрев на него, он разделил все слова на четыре группы по форме букв:\n1) <em>ананас</em>, <em>котлета</em>, <em>сок</em>;\n2) <em>банан</em>, <em>кабачок</em>, <em>слойка</em>;\n3) <em>огурец</em>, <em>репа</em>, <em>суп</em>;\n4) <em>абрикос</em>, <em>булка, грейпфрут</em>.\nВ какие группы Вася отнёс слова <em>борщ</em> и <em>молоко</em>?","choices":["<em>борщ</em> — в первую, <em>молоко</em> — в третью","<em>борщ</em> — во вторую, <em>молоко</em> — в четвёртую","<em>борщ</em> — в третью, <em>молоко</em> — во вторую","<em>борщ</em> — в третью, <em>молоко</em> — в первую","<em>борщ</em> — в четвёртую, <em>молоко</em> — в первую."],"key":"Д","review":["Форма букв в списке","Проверь выступы у строчных букв. В первой группе их нет, во второй есть только верхние (б или й), в третьей — только нижние (например, у или ц), в четвёртой — оба вида.","У «борщ» б поднимается, а р и щ опускаются, поэтому это четвёртая группа. У «молоко» ни одного выступа, поэтому это первая группа."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
